function refreshAssetBreadcrumb(e,t,o){$.ajax({method:"GET",url:`${CFG_GLPI.root_doc}/ajax/cable.php`,data:{action:"get_item_breadcrum",items_id:t,itemtype:e}}).then(e=>{$(`#${CSS.escape(o)}`).empty();$(`#${CSS.escape(o)}`).append(e)})}function refreshNetworkPortDropdown(e,t,o){$.ajax({method:"GET",url:`${CFG_GLPI.root_doc}/ajax/cable.php`,data:{action:"get_networkport_dropdown",items_id:t,itemtype:e}}).then(e=>{$(`#${CSS.escape(o)}`).empty();$(`#${CSS.escape(o)}`).append(e)})}function refreshSocketDropdown(e,t,o,r){$.ajax({method:"GET",url:`${CFG_GLPI.root_doc}/ajax/cable.php`,data:{action:"get_socket_dropdown",items_id:t,itemtype:e,socketmodels_id:o,dom_name:r}}).then(e=>{const t=$(`select[name="${CSS.escape(r)}"]`).parent().parent();t.empty();t.append(e)})}if(typeof module!=="undefined"&&module.exports){module.exports={refreshAssetBreadcrumb:refreshAssetBreadcrumb,refreshNetworkPortDropdown:refreshNetworkPortDropdown,refreshSocketDropdown:refreshSocketDropdown}}